let localDataDir: string;
let nvmDir: string;

const ok = ( stdout = '' ): CommandResult => ( { ok: true, stdout, stderr: '' } );
const fail = ( stderr: string ): CommandResult => ( { ok: false, stdout: '', stderr } );

function runner( overrides: Record<string, CommandResult> = {} ): CommandRunner {
	const defaults: Record<string, CommandResult> = {
		'git rev-parse': ok( 'release/4.17.5\n' ),
		'git tag': ok( '4.17.4.1\n4.17.4\n' ),
		'git status': ok( '' ),
		'gh auth': ok( '' ),
		'docker ps': ok( 'abc123-wordpress-1\nabc123-mysql-1\n' ),
		'svn --version': ok( '1.14.5\n' ),
		'security find-generic-password': ok( 'keychain: "login"\nattributes:\n    "acct"<blob>="prappo"\n    "svce"<blob>="wpsp-wporg-svn"\n' ),
	};

	return async ( command, args ) => {
		const key = `${ command } ${ args[ 0 ] }`;

		return overrides[ key ] ?? defaults[ key ] ?? fail( 'unexpected command' );
	};
}

function addLocalSite( id: string, sitePath: string, running: boolean ): void {
	const file = path.join( localDataDir, 'sites.json' );
	let sites: Record<string, unknown> = {};

	try {
		sites = JSON.parse( readFileSync( file, 'utf8' ) );
	} catch {
		sites = {};
	}

	sites[ id ] = { name: id, path: sitePath };
	writeFileSync( file, JSON.stringify( sites ) );

	if ( running ) {
		mkdirSync( path.join( localDataDir, 'run', id, 'mysql' ), { recursive: true } );
		writeFileSync( path.join( localDataDir, 'run', id, 'mysql', 'mysqld.sock' ), '' );
	}
}

async function checksById( overrides: Record<string, CommandResult> = {}, version = '4.17.5' ) {
	const checks = await healthChecks( { root, version: parseVersion( version ), run: runner( overrides ), localDataDir, nvmDir } );

	return Object.fromEntries( checks.map( ( item ) => [ item.id, item ] ) );
}

beforeEach( () => {
	base = mkdtempSync( path.join( tmpdir(), 'release-console-health-' ) );
	root = path.join( base, 'sites/wpsp/app/public/wp-content/plugins/wp-simple-pay-pro' );
	localDataDir = path.join( base, 'local' );
	nvmDir = path.join( base, 'nvm' );
	mkdirSync( root, { recursive: true } );
	mkdirSync( localDataDir );
	mkdirSync( path.join( nvmDir, 'v16.20.2' ), { recursive: true } );
} );

afterEach( () => rmSync( base, { recursive: true, force: true } ) );

describe( 'healthChecks', () => {
	it( 'passes the git, gh, wp-env and Node checks on a ready machine', async () => {
		const checks = await checksById( { 'gh auth': ok( '✓ Logged in to github.com account prappo (keyring)' ) } );

		expect( checks.branch ).toMatchObject( { status: 'ok', detail: 'On release/4.17.5.' } );
		expect( checks[ 'previous-tag' ] ).toMatchObject( { status: 'info', detail: 'Latest release tag is 4.17.4.1.' } );
		expect( checks[ 'working-tree' ] ).toMatchObject( { detail: 'Clean.' } );
		expect( checks.gh ).toMatchObject( { status: 'ok', detail: 'Logged in as prappo.' } );
		expect( checks[ 'wp-env' ].status ).toBe( 'ok' );
		expect( checks.node16 ).toMatchObject( { status: 'ok', detail: expect.stringContaining( 'v16.20.2' ) } );
	} );

	it( 'warns about the wrong branch and a missing tag, and counts changes', async () => {
		const checks = await checksById( {
			'git rev-parse': ok( 'master\n' ),
			'git tag': ok( '' ),
			'git status': ok( ' M a\0?? b\0?? tools/release-console/server/app.ts\0' ),
		} );

		expect( checks.branch ).toMatchObject( { status: 'warn', detail: expect.stringContaining( 'not release/4.17.5 or hotfix/4.17.5' ) } );
		expect( checks[ 'previous-tag' ].status ).toBe( 'warn' );
		// The console's own files are not counted, matching the Changes tab.
		expect( checks[ 'working-tree' ].detail ).toBe( '2 uncommitted changes.' );
	} );

	it( 'skips the branch check without a version', async () => {
		const checks = await healthChecks( { root, version: null, run: runner(), localDataDir, nvmDir } );

		expect( checks.find( ( item ) => item.id === 'branch' ) ).toBeUndefined();
	} );

	it( 'fails gh when it is logged out or missing', async () => {
		expect( ( await checksById( { 'gh auth': fail( 'You are not logged into any GitHub hosts.' ) } ) ).gh ).toMatchObject( {
			status: 'fail',
			detail: expect.stringContaining( 'gh auth login' ),
		} );
		expect( ( await checksById( { 'gh auth': fail( 'spawn gh ENOENT' ) } ) ).gh.detail ).toContain( 'not installed' );
	} );

	it( 'warns when Docker or wp-env is not running', async () => {
		expect( ( await checksById( { 'docker ps': fail( 'Cannot connect to the Docker daemon' ) } ) )[ 'wp-env' ] ).toMatchObject( {
			status: 'warn',
			detail: expect.stringContaining( 'Docker is not running' ),
		} );
		expect( ( await checksById( { 'docker ps': ok( 'some-other-container\n' ) } ) )[ 'wp-env' ].detail ).toContain( 'Not running' );
	} );

	it( 'warns when Node 16 is missing', async () => {
		rmSync( nvmDir, { recursive: true } );

		expect( ( await checksById() ).node16.status ).toBe( 'warn' );
	} );

	it( 'reports the Local site as running, stopped, or not found', async () => {
		expect( ( await checksById() )[ 'local-site' ] ).toMatchObject( { status: 'warn', detail: expect.stringContaining( 'not inside a Local' ) } );

		addLocalSite( 'abc', path.join( base, 'sites/wpsp' ), false );
		expect( ( await checksById() )[ 'local-site' ] ).toMatchObject( { status: 'fail', detail: 'abc is stopped. Start it in Local.' } );

		addLocalSite( 'abc', path.join( base, 'sites/wpsp' ), true );
		expect( ( await checksById() )[ 'local-site' ] ).toMatchObject( { status: 'ok', detail: 'abc is running.' } );
	} );

	it( 'checks the marketing site from Settings', async () => {
		expect( ( await checksById() )[ 'marketing-site' ] ).toMatchObject( { status: 'warn', detail: expect.stringContaining( 'Set it in Settings' ) } );

		const site = path.join( base, 'sites/wpsp-site/app/public/wp-content/plugins/wpsp-docs' );
		mkdirSync( path.join( site, 'docs-user' ), { recursive: true } );
		writeFileSync( path.join( site, 'package.json' ), '{}' );
		mkdirSync( path.join( root, '.claude' ) );
		writeFileSync( path.join( root, CONFIG_FILE ), JSON.stringify( { marketingSitePath: site } ) );

		expect( ( await checksById() )[ 'marketing-site' ].detail ).toContain( 'not inside a Local site' );

		addLocalSite( 'site1', path.join( base, 'sites/wpsp-site' ), false );
		expect( ( await checksById() )[ 'marketing-site' ].status ).toBe( 'fail' );

		addLocalSite( 'site1', path.join( base, 'sites/wpsp-site' ), true );
		expect( ( await checksById() )[ 'marketing-site' ] ).toMatchObject( { status: 'ok', detail: 'site1 is running.' } );
	} );

	it( 'checks the Lite checkout', async () => {
		expect( ( await checksById() ).lite ).toMatchObject( { status: 'warn', detail: expect.stringContaining( 'clone it there on first use' ) } );

		const lite = path.join( path.dirname( root ), 'wp-simple-pay-lite' );
		mkdirSync( lite );
		expect( ( await checksById() ).lite.status ).toBe( 'fail' );

		writeFileSync( path.join( lite, 'stripe-checkout.php' ), '<?php' );
		expect( ( await checksById() ).lite ).toMatchObject( { status: 'ok', detail: lite } );
	} );

	it( 'checks svn and where the wp.org working copy is', async () => {
		const wc = path.join( path.dirname( root ), 'stripe-svn' );

		expect( ( await checksById() ).svn ).toMatchObject( { status: 'ok', stages: [ 'lite-wporg' ], detail: expect.stringContaining( `${ wc } (checked out on first use)` ) } );

		mkdirSync( path.join( wc, '.svn' ), { recursive: true } );
		expect( ( await checksById() ).svn.detail ).toBe( `svn 1.14.5. Working copy: ${ wc }. Logged in to wp.org as prappo.` );

		const loggedOut = ( await checksById( { 'security find-generic-password': fail( 'The specified item could not be found in the keychain.' ) } ) ).svn;
		expect( loggedOut ).toMatchObject( { status: 'warn', detail: expect.stringContaining( 'svn-login.sh' ) } );

		expect( ( await checksById( { 'svn --version': fail( 'spawn svn ENOENT' ) } ) ).svn ).toMatchObject( { status: 'fail', detail: expect.stringContaining( 'brew install subversion' ) } );
	} );

	it( 'names the stages each check affects', async () => {
		const checks = await checksById();

		expect( checks.gh.stages ).toContain( 'create-release' );
		expect( checks[ 'local-site' ].stages ).toEqual( [ 'notifications' ] );
		expect( checks[ 'wp-env' ].stages ).toEqual( [ 'docs' ] );
	} );
} );

describe( 'Local sites', () => {
	it( 'reads sites.json, expanding ~, and copes with a missing or bad file', () => {
		expect( localSites( localDataDir ) ).toEqual( [] );

		writeFileSync( path.join( localDataDir, 'sites.json' ), '{bad' );
		expect( localSites( localDataDir ) ).toEqual( [] );

		writeFileSync( path.join( localDataDir, 'sites.json' ), JSON.stringify( { a: { name: 'wpsp', path: '~/Local Sites/wpsp' }, b: { name: 'no path' } } ) );
		expect( localSites( localDataDir ) ).toEqual( [ { id: 'a', name: 'wpsp', path: path.join( homedir(), 'Local Sites/wpsp' ) } ] );
	} );

	it( 'matches a folder inside a site, not one that only shares a prefix', () => {
		const sites = [ { id: 'a', name: 'wpsp', path: '/sites/wpsp' } ];

		expect( siteFor( sites, '/sites/wpsp/app/public' )?.id ).toBe( 'a' );
		expect( siteFor( sites, '/sites/wpsp' )?.id ).toBe( 'a' );
		expect( siteFor( sites, '/sites/wpsp-site/app' ) ).toBeNull();
	} );
} );

describe( 'previous release tag', () => {
	it( 'picks the highest plain version, ignoring v-prefixed and other tags', () => {
		expect( latestReleaseTag( [ 'v4.17.3', '4.17.4.1', '4.17.4', '4.9.0', 'beta-1', '4.17.10' ] ) ).toBe( '4.17.10' );
		expect( latestReleaseTag( [ '4.17.4', '4.17.4.1' ] ) ).toBe( '4.17.4.1' );
		expect( latestReleaseTag( [ 'v1', 'nightly' ] ) ).toBeNull();
		expect( latestReleaseTag( [] ) ).toBeNull();
	} );

	it( 'warns when git’s version sort would put a prefixed tag first, as Analyze does', async () => {
		const checks = await checksById( { 'git tag': ok( 'v4.17.3\n4.17.4.1\n4.17.4\n' ) } );

		expect( checks[ 'previous-tag' ] ).toMatchObject( {
			status: 'warn',
			detail: expect.stringContaining( 'lists v4.17.3 first' ),
			stages: [ 'analyze' ],
		} );
	} );
} );
